CREATE TABLE branch (id INTEGER PRIMARY KEY, code TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(code) BETWEEN 1 AND 32), name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 100), is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE outlet (id INTEGER PRIMARY KEY, branch_id INTEGER NOT NULL, code TEXT NOT NULL COLLATE NOCASE CHECK(length(code) BETWEEN 1 AND 32), name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 100), is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(branch_id,code), FOREIGN KEY(branch_id) REFERENCES branch(id) ON DELETE RESTRICT);
CREATE INDEX idx_outlet_branch_active ON outlet(branch_id,is_active,name);
CREATE TABLE ip_range (id INTEGER PRIMARY KEY, branch_id INTEGER NOT NULL, cidr TEXT NOT NULL CHECK(length(cidr) BETWEEN 7 AND 18), subnet_mask TEXT NOT NULL, gateway TEXT NOT NULL, dns_primary TEXT NOT NULL, dns_secondary TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(branch_id,cidr), FOREIGN KEY(branch_id) REFERENCES branch(id) ON DELETE RESTRICT);
CREATE TABLE ip_address_pool (id INTEGER PRIMARY KEY, ip_range_id INTEGER NOT NULL, ip_address TEXT NOT NULL UNIQUE, is_reserved INTEGER NOT NULL DEFAULT 0 CHECK(is_reserved IN (0,1)), reservation_reason TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), FOREIGN KEY(ip_range_id) REFERENCES ip_range(id) ON DELETE RESTRICT);
CREATE INDEX idx_ip_pool_range_available ON ip_address_pool(ip_range_id,is_active,is_reserved,ip_address);

CREATE TABLE sys_user (id INTEGER PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(username) BETWEEN 3 AND 64), password_hash TEXT NOT NULL, real_name TEXT NOT NULL CHECK(length(real_name) BETWEEN 1 AND 100), role TEXT NOT NULL CHECK(role IN ('ADMIN','TECH_ADMIN','TECH_ADMIN_BACKUP')), branch_id INTEGER, outlet_id INTEGER, parent_user_id INTEGER UNIQUE, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), must_change_password INTEGER NOT NULL DEFAULT 1 CHECK(must_change_password IN (0,1)), failed_login_count INTEGER NOT NULL DEFAULT 0, locked_until TEXT, password_changed_at TEXT, last_login_at TEXT, created_by INTEGER, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), version INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(branch_id) REFERENCES branch(id) ON DELETE RESTRICT, FOREIGN KEY(outlet_id) REFERENCES outlet(id) ON DELETE RESTRICT, FOREIGN KEY(parent_user_id) REFERENCES sys_user(id) ON DELETE RESTRICT, FOREIGN KEY(created_by) REFERENCES sys_user(id) ON DELETE RESTRICT);
CREATE INDEX idx_user_scope ON sys_user(branch_id,outlet_id,role,is_active);
CREATE TABLE sys_session (id INTEGER PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE CHECK(length(token_hash)=64), csrf_token_hash TEXT NOT NULL CHECK(length(csrf_token_hash)=64), user_id INTEGER NOT NULL, expires_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), FOREIGN KEY(user_id) REFERENCES sys_user(id) ON DELETE CASCADE);
CREATE INDEX idx_session_user_active ON sys_session(user_id,revoked_at,expires_at);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY, request_id TEXT, actor_user_id INTEGER, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, result TEXT NOT NULL CHECK(result IN ('SUCCESS','FAILURE')), detail_json TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), FOREIGN KEY(actor_user_id) REFERENCES sys_user(id) ON DELETE RESTRICT);
CREATE INDEX idx_audit_actor_time ON audit_log(actor_user_id,created_at);
CREATE TABLE system_config (id INTEGER PRIMARY KEY, config_key TEXT NOT NULL UNIQUE, config_value TEXT NOT NULL, description TEXT, updated_by INTEGER, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), FOREIGN KEY(updated_by) REFERENCES sys_user(id) ON DELETE RESTRICT);
INSERT INTO system_config(config_key,config_value,description) VALUES('release_countdown_hours','12','IP撤销后的释放倒计时小时数，仅影响后续阶段新撤销记录');
